-- A57: batch b001_es, chunk 3 (25 videos for learners of es). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'es' and media_id in (670,155,5282,602,4827,7853,144,5012,57,5382,353,5560,5506,4603,122,339,368,5062,472,680,4941,3,30,31,100)) then
    raise exception 'A57 out/b001_es_03.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'es' and media_id in (670,155,5282,602,4827,7853,144,5012,57,5382,353,5560,5506,4603,122,339,368,5062,472,680,4941,3,30,31,100)) <> 25 then
    raise exception 'A57 out/b001_es_03.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
